const pagerdutyApp = new logfire.Channel("pagerdutyApp", {config: [{
    type: "pagerduty-integration",
    installId: onCall.then(onCall => onCall.installId),
    serviceId: onCall.then(onCall => onCall.serviceId),
}]});
